mapper.select:
SELECT p.id, p.member_id, p.category_id, c.name AS category_name, p.content, p.image_url, p.like_count, p.view_count, p.subscriber_only, p.created_at, p.updated_at FROM post p JOIN common_code c ON p.category_id = c.id WHERE p.subscriber_only = FALSE
AND p.id < #{cursor}
ORDER BY p.id DESC LIMIT #{size}

SELECT p.id, p.member_id, p.category_id, c.name AS category_name, p.content, p.image_url, p.like_count, p.view_count, p.subscriber_only, p.created_at, p.updated_at FROM post p INNER JOIN subscription s ON s.target_id = p.member_id JOIN common_code c ON p.category_id = c.id WHERE s.member_id = #{memberId} AND s.status_id = 15 AND p.subscriber_only = TRUE
AND p.id < #{cursor}
ORDER BY p.id DESC LIMIT #{size}

mapper.update:
UPDATE post
SET category_id = #{categoryId}, content = #{content}, image_url = #{imageUrl}, subscriber_only = #{subscriberOnly}
WHERE id = #{id}
